 static String[] positions(Context c){String l=c.getResources().getConfiguration().locale.getLanguage();String left="cs".equals(l)?"Vlevo":"de".equals(l)?"Links":"fr".equals(l)?"Gauche":"es".equals(l)?"Izquierda":"pl".equals(l)?"Lewo":"Left";String right="cs".equals(l)?"Vpravo":"de".equals(l)?"Rechts":"fr".equals(l)?"Droite":"es".equals(l)?"Derecha":"pl".equals(l)?"Prawo":"Right";String top="cs".equals(l)?"Nahoře":"de".equals(l)?"Oben":"fr".equals(l)?"Haut":"es".equals(l)?"Arriba":"pl".equals(l)?"Góra":"Top";String bottom="cs".equals(l)?"Dole":"de".equals(l)?"Unten":"fr".equals(l)?"Bas":"es".equals(l)?"Abajo":"pl".equals(l)?"Dół":"Bottom";return new String[]{left+" 1",left+" 2",left+" 3",left+" 4",top,right+" 4",right+" 3",right+" 2",right+" 1",bottom};}
